// 대표 v3 classroom-flow src/ui/FlowLocale.tsx 그대로
import {createContext,useContext,useSyncExternalStore,useState,type ReactNode} from 'react';
import {LANGUAGES,resolveLocale,translate,direction} from '../shared/i18n.mjs';
const Context=createContext<string|null>(null);
const getLocale=()=>typeof document==='undefined'?'ko':resolveLocale(document.documentElement.lang)??'ko';
function subscribe(callback:()=>void){const observer=new window.MutationObserver(callback);observer.observe(document.documentElement,{attributes:true,attributeFilter:['lang']});return()=>observer.disconnect();}
export function FlowLocaleProvider({locale,children}:{locale:string;children:ReactNode}){return <Context.Provider value={resolveLocale(locale)??'ko'}>{children}</Context.Provider>;}
export function useFlowLocale(){const override=useContext(Context);const documentLocale=useSyncExternalStore(subscribe,getLocale,()=> 'ko');const locale=override??documentLocale;return {locale,dir:direction(locale),t:(key:string,vars?:Record<string,string|number>)=>translate(locale,key,vars)};}
export function FlowLanguageSelect({locale,onChange}:{locale:string;onChange:(value:string)=>void}){return <label className="flow-language">{translate(locale,'language')}<select value={locale} onChange={e=>onChange(e.target.value)}>{LANGUAGES.map(l=><option key={l.code} value={l.code} lang={l.code}>{l.name}</option>)}</select></label>;}
export function FlowFrame({children,label}:{children:ReactNode;label?:string}){const {locale,dir,t}=useFlowLocale();return <section className="flow-ui" lang={locale} dir={dir} aria-label={label?t(label):undefined}><style>{`.flow-ui{min-width:0;max-width:100%;overflow-wrap:anywhere;text-align:start}.flow-ui *{box-sizing:border-box}.flow-ui label{display:block;margin-block:8px}.flow-ui input:not([type=checkbox]),.flow-ui textarea,.flow-ui select{max-width:100%;width:100%;min-width:0;padding:8px;border:1px solid #b6c2cc;border-radius:7px;background:transparent;color:inherit}.flow-ui textarea{min-height:70px;resize:vertical}.flow-ui button,.flow-ui .flow-link{min-height:44px;max-width:100%;white-space:normal;overflow-wrap:anywhere;padding:9px 13px;border:1px solid #b6c2cc;border-radius:8px;margin:4px;cursor:pointer}.flow-ui button:disabled{opacity:.55;cursor:default}.flow-ui fieldset,.flow-ui article,.flow-ui aside{min-width:0;margin-block:14px;padding:14px;border:1px solid #cbd5e1;border-radius:12px}.flow-ui legend{max-width:100%;white-space:normal}.flow-ui p{white-space:pre-wrap}.flow-ui .flow-scroll{max-width:100%;overflow-x:auto}.flow-ui table{border-collapse:collapse;width:100%}.flow-ui td,.flow-ui th{border:1px solid #cbd5e1;padding:8px;min-width:130px;text-align:start}.flow-ui .flow-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:12px}.flow-ui .flow-language{max-width:280px}.flow-ui bdi{unicode-bidi:isolate}`}</style>{children}</section>;}


export function FlowText({messageKey}:{messageKey:string}){const {t}=useFlowLocale();return <>{t(messageKey)}</>;}
export function StandaloneFlowLocale({children}:{children:ReactNode}){
 const [locale,setLocale]=useState(()=>{try{return resolveLocale(new URLSearchParams(window.location.search).get('lang'))??resolveLocale(localStorage.getItem('feelgood:flow-language'))??getLocale();}catch{return getLocale();}});
 return <FlowLocaleProvider locale={locale}><FlowFrame><FlowLanguageSelect locale={locale} onChange={code=>{const next=resolveLocale(code);if(!next)return;setLocale(next);try{localStorage.setItem('feelgood:flow-language',next);const url=new URL(window.location.href);url.searchParams.set('lang',next);history.replaceState(history.state,'',url);}catch{/* In-memory preference still applies. */}}}/></FlowFrame>{children}</FlowLocaleProvider>;
}
